mapper.select:
SELECT id, sheet_id, row_index, col_index, cell_value, cell_formula, cell_type, cell_style, create_time, update_time
FROM work_report_cell
WHERE sheet_id = #{sheetId}
  AND row_index BETWEEN #{startRow} AND #{endRow}
  AND col_index BETWEEN #{startCol} AND #{endCol}
ORDER BY row_index ASC, col_index ASC

mapper.delete:
DELETE c FROM work_report_cell c
INNER JOIN work_report_sheet s ON c.sheet_id = s.id
WHERE s.report_id = #{reportId}

DELETE FROM work_report_cell
WHERE sheet_id = #{sheetId}
  AND row_index BETWEEN #{startRow} AND #{endRow}
  AND col_index BETWEEN #{startCol} AND #{endCol}
